# shellcheck shell=bash
# third_party/x11/cross/env.sh -- shared cross environment for the X11 stack.
#
#   . third_party/x11/cross/env.sh <arm|intel> <PREFIX> [TOOLS_DIR]
#
# Sourced by build.sh (and usable by hand / by other lanes' build-<stage>.sh).
# Mirrors the repo's USER_CFLAGS (Makefile) and ~/webkit-hobbyos toolchain:
# clang --target=<triple> -ffreestanding, hermetic -nostdinc search path,
# the repo libc headers src/libc/include + src/include + src/user_include,
# static everything, flat-binary link model (crt0.o + libc.a [+ libcxx.a],
# -T src/user/linker.ld, objcopy -O binary).
#
# It (re)generates small per-repo wrapper tools in TOOLS_DIR (default
# third_party/x11/build/<arch>/tools — NOT the shared prefix, so concurrent
# lanes sharing one prefix never overwrite each other's wrappers):
#   hobbyos-cc / hobbyos-c++   clang driver wrappers.  Compile mode = plain
#                              clang + target flags.  Link mode (no -c/-S/-E)
#                              appends -nostdlib, the linker script and the
#                              sysroot closure, so autoconf/meson/cmake link
#                              probes produce real HobbyOS ELF images.
#   hobbyos-pkg-config         pkg-config restricted to PREFIX, always --static.
#   meson-paths.ini            [constants] for cross/meson-<arch>.ini.
#
# Exports: HB_ARCH HB_TRIPLE HB_REPO HB_X11 HB_PREFIX HB_TOOLS HB_OBJ
#          HB_ARCH_CFLAGS HB_SYSINC HB_CFLAGS HB_CXXFLAGS HB_LIBCXX_INC
#          HB_CONFIGURE_ARGS CC CXX CPP CFLAGS CXXFLAGS CPPFLAGS LDFLAGS LIBS
#          AR RANLIB NM STRIP OBJCOPY LD PKG_CONFIG PKG_CONFIG_LIBDIR
#          PKG_CONFIG_PATH PKG_CONFIG_SYSROOT_DIR CC_FOR_BUILD

if [ $# -lt 2 ]; then
  echo "usage: . cross/env.sh <arm|intel> <PREFIX> [TOOLS_DIR]" >&2
  return 2 2>/dev/null || exit 2
fi

HB_ARCH="$1"
HB_X11="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
HB_REPO="$(cd "$HB_X11/../.." && pwd)"
mkdir -p "$2"
HB_PREFIX="$(cd "$2" && pwd)"
HB_TOOLS="${3:-$HB_X11/build/$HB_ARCH/tools}"
mkdir -p "$HB_TOOLS"
HB_TOOLS="$(cd "$HB_TOOLS" && pwd)"

# Host llvm tools (llvm-ar etc. live only here on the workstation).
case ":$PATH:" in *":/usr/lib/llvm-21/bin:"*) ;; *) [ -d /usr/lib/llvm-21/bin ] && PATH="$PATH:/usr/lib/llvm-21/bin";; esac
export PATH

case "$HB_ARCH" in
  arm)   HB_TRIPLE=aarch64-none-elf; HB_CPU=aarch64
         HB_ARCH_CFLAGS="-mcpu=cortex-a53"; HB_ARCH_LDFLAGS="" ;;
  intel) HB_TRIPLE=x86_64-none-elf; HB_CPU=x86_64
         HB_ARCH_CFLAGS="-mno-red-zone -mcmodel=large"; HB_ARCH_LDFLAGS="-Wl,-no-pie" ;;
  *) echo "env.sh: arch must be arm or intel (got '$HB_ARCH')" >&2; return 2 2>/dev/null || exit 2 ;;
esac

HB_OBJ="$HB_REPO/obj/$HB_ARCH"
HB_LSCRIPT="$HB_REPO/src/user/linker.ld"
HB_CLANG_RES="$(clang -print-resource-dir)/include"
HB_LIBCXX_INC="$HB_REPO/third_party/libcxx-21.1.8/src/llvm-project-21.1.8.src/libcxx/include"
# Search order: the X11-only overlay (cross/include: POSIX limits the repo
# libc deliberately lacks), then repo libc headers (they own stdint/limits/stdarg...),
# then the kernel/user shared headers, then clang's freestanding resource
# headers.  -isystem keeps package -I dirs (automake/meson) ahead of them.
HB_SYSINC="-nostdinc -isystem $HB_X11/cross/include -isystem $HB_REPO/src/libc/include -isystem $HB_REPO/src/include -isystem $HB_REPO/src/user_include -isystem $HB_CLANG_RES"
HB_TARGET="--target=$HB_TRIPLE -ffreestanding $HB_ARCH_CFLAGS"
# Transitional: until lane kern's named-socket wrappers are merged, force-
# include POSIX socket prototypes (cross/compat/hb-socket-compat.h).
HB_COMPAT_INC=""
if ! grep -Eq '\<bind[[:space:]]*\(' "$HB_REPO/src/libc/include/sys/socket.h"; then
  HB_COMPAT_INC="-include $HB_X11/cross/compat/hb-socket-compat.h"
fi
HB_CFLAGS="-O2 -g -fno-common -Wno-error"
# C++ (icewm lane): libc++ first (its C-compat wrappers #include_next the
# sysroot C headers), no exceptions, RTTI on (libcxx.a has the closure).
HB_CXXFLAGS="-O2 -g -std=c++17 -fno-exceptions -frtti -nostdinc++ -isystem $HB_LIBCXX_INC"

# ---- wrapper tools -------------------------------------------------------
# Link note: on intel clang's x86_64-none-elf driver links through the host
# gcc driver (-fuse-ld=lld still makes ld.lld do the work); gcc adds
# --build-id, whose .note section would land at the image base ahead of
# _start, so --build-id=none is mandatory (the flat loader enters at base).
_hb_write_cc() { # _hb_write_cc <path> <c|c++>
  local cxx_inc="" cxx_lang="" closure="$HB_COMPAT_LIB $HB_OBJ/libc.a"
  if [ "$2" = c++ ]; then
    cxx_lang="-fno-exceptions -frtti"
    cxx_inc="-nostdinc++ -isystem $HB_LIBCXX_INC"
    closure="$HB_COMPAT_LIB $HB_OBJ/libcxx.a $HB_OBJ/libc.a"
  fi
  cat > "$1.tmp" <<EOF
#!/usr/bin/env bash
# Generated by third_party/x11/cross/env.sh -- HobbyOS $HB_ARCH $2 driver.
link=1
for a in "\$@"; do
  case "\$a" in -c|-S|-E|-M|-MM|-fsyntax-only|--version|-v|-dumpversion|-dumpmachine|-print-*) link=0;; esac
done
if [ \$link = 1 ]; then
  exec clang $HB_TARGET $cxx_lang $cxx_inc $HB_SYSINC \\
    -nostdlib -static -fuse-ld=lld $HB_ARCH_LDFLAGS -Wl,--build-id=none -Wl,-T,$HB_LSCRIPT -Wl,-e,_start \\
    $HB_OBJ/crt0.o "\$@" -L$HB_TOOLS/lib -Wl,--start-group $closure -Wl,--end-group
fi
exec clang $HB_TARGET $cxx_lang $cxx_inc $HB_SYSINC $HB_COMPAT_INC "\$@"
EOF
  chmod +x "$1.tmp"; mv "$1.tmp" "$1"
}
# Empty libc.a/libm.a/libpthread.a/... so `-lc -lm -lpthread` probes
# (AC_CHECK_LIB(c, ...), meson dependency('threads')) resolve: the real
# closure (one libc.a holds libc+libm+pthread) is appended by the wrapper.
mkdir -p "$HB_TOOLS/lib"
for _l in c m pthread rt dl util; do
  [ -f "$HB_TOOLS/lib/lib$_l.a" ] || llvm-ar rcs "$HB_TOOLS/lib/lib$_l.a"
done
# Transitional (see HB_COMPAT_INC): ENOSYS link stubs for the named-socket
# API until lane kern's libc wrappers are merged.
HB_COMPAT_LIB=""
if [ -n "$HB_COMPAT_INC" ]; then
  if [ ! -f "$HB_TOOLS/lib/libhbsockcompat.a" ] || [ "$HB_X11/cross/compat/hb-socket-stubs.c" -nt "$HB_TOOLS/lib/libhbsockcompat.a" ]; then
    clang $HB_TARGET $HB_SYSINC $HB_COMPAT_INC -O2 -c "$HB_X11/cross/compat/hb-socket-stubs.c" -o "$HB_TOOLS/lib/hb-socket-stubs.o" &&
      rm -f "$HB_TOOLS/lib/libhbsockcompat.a" &&
      llvm-ar rcs "$HB_TOOLS/lib/libhbsockcompat.a" "$HB_TOOLS/lib/hb-socket-stubs.o"
  fi
  HB_COMPAT_LIB="$HB_TOOLS/lib/libhbsockcompat.a"
else
  rm -f "$HB_TOOLS/lib/libhbsockcompat.a" "$HB_TOOLS/lib/hb-socket-stubs.o"
fi
_hb_write_cc "$HB_TOOLS/hobbyos-cc" c
_hb_write_cc "$HB_TOOLS/hobbyos-c++" c++

cat > "$HB_TOOLS/hobbyos-pkg-config.tmp" <<EOF
#!/bin/sh
# Generated by third_party/x11/cross/env.sh: pkg-config confined to the
# HobbyOS X11 prefix ($HB_PREFIX); always static.
PKG_CONFIG_LIBDIR="$HB_PREFIX/lib/pkgconfig:$HB_PREFIX/share/pkgconfig"
PKG_CONFIG_PATH=
PKG_CONFIG_SYSROOT_DIR=
export PKG_CONFIG_LIBDIR PKG_CONFIG_PATH PKG_CONFIG_SYSROOT_DIR
exec pkg-config --static "\$@"
EOF
chmod +x "$HB_TOOLS/hobbyos-pkg-config.tmp"; mv "$HB_TOOLS/hobbyos-pkg-config.tmp" "$HB_TOOLS/hobbyos-pkg-config"

cat > "$HB_TOOLS/meson-paths.ini" <<EOF
# Generated by third_party/x11/cross/env.sh; pass BEFORE cross/meson-$HB_ARCH.ini.
[constants]
hb_tools = '$HB_TOOLS'
hb_prefix = '$HB_PREFIX'
hb_repo = '$HB_REPO'
EOF

# ---- exported environment (autotools) -------------------------------------
export HB_ARCH HB_TRIPLE HB_CPU HB_REPO HB_X11 HB_PREFIX HB_TOOLS HB_OBJ HB_LSCRIPT \
       HB_ARCH_CFLAGS HB_ARCH_LDFLAGS HB_SYSINC HB_COMPAT_INC HB_COMPAT_LIB HB_TARGET HB_CFLAGS HB_CXXFLAGS HB_LIBCXX_INC
export CC="$HB_TOOLS/hobbyos-cc"
export CXX="$HB_TOOLS/hobbyos-c++"
export CPP="$HB_TOOLS/hobbyos-cc -E"
export CFLAGS="$HB_CFLAGS"
export CXXFLAGS="$HB_CXXFLAGS"
export CPPFLAGS="-I$HB_PREFIX/include"
export LDFLAGS="-L$HB_PREFIX/lib"
export LIBS=""
export AR=llvm-ar RANLIB=llvm-ranlib NM=llvm-nm STRIP=llvm-strip OBJCOPY=llvm-objcopy LD=ld.lld
export PKG_CONFIG="$HB_TOOLS/hobbyos-pkg-config"
export PKG_CONFIG_LIBDIR="$HB_PREFIX/lib/pkgconfig:$HB_PREFIX/share/pkgconfig"
export PKG_CONFIG_PATH="" PKG_CONFIG_SYSROOT_DIR=""
# Host compiler for build-time generators (libX11 makekeys etc.).
export CC_FOR_BUILD="${CC_FOR_BUILD:-cc}" CPP_FOR_BUILD="${CPP_FOR_BUILD:-cc -E}"
export CFLAGS_FOR_BUILD="" CPPFLAGS_FOR_BUILD="" LDFLAGS_FOR_BUILD=""
export CPATH="" C_INCLUDE_PATH="" CPLUS_INCLUDE_PATH="" LIBRARY_PATH=""
HB_CONFIGURE_ARGS="--host=$HB_TRIPLE --build=$(uname -m)-pc-linux-gnu --prefix=$HB_PREFIX --disable-shared --enable-static"
export HB_CONFIGURE_ARGS
